import{_ as o}from"./plugin-vue_export-helper-c27b6911.js";import{r as i,o as r,c,d as h,a as t,e as l,w as a,b as e,f as s}from"./app-99582225.js";const p={},_=t("div",{class:"hint-container tip"},[t("p",{class:"hint-container-title"},"读前须知"),t("p",null,"需要第 08 篇的跳转函数与两阶段求解。本篇解读一篇论文的数据布局和回收优化，第 6 节补充其他优化路线。")],-1),f=t("code",null,"〈源事实,目标点,目标事实,函数〉",-1),g=t("em",null,"Scaling Interprocedural Static Data-Flow Analysis to Large C/C++ Applications: An Experience Report",-1),u={href:"https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ECOOP.2024.36",target:"_blank",rel:"noopener noreferrer"},x=s('<h2 id="_1-跳转函数的访问成本" tabindex="-1"><a class="header-anchor" href="#_1-跳转函数的访问成本" aria-hidden="true">#</a> 1. 跳转函数的访问成本</h2><p>假设节点 n 处有三条跳转函数：</p><table><thead><tr><th style="text-align:left;">源事实 d₁</th><th style="text-align:left;">目标事实 d₂</th><th style="text-align:left;">函数</th></tr></thead><tbody><tr><td style="text-align:left;">p</td><td style="text-align:left;">a</td><td style="text-align:left;"><code>t↦t+2</code></td></tr><tr><td style="text-align:left;">p</td><td style="text-align:left;">b</td><td style="text-align:left;"><code>t↦5(t+2)</code></td></tr><tr><td style="text-align:left;">q</td><td style="text-align:left;">b</td><td style="text-align:left;">恒等</td></tr></tbody></table><p>更新一条记录需要查找旧函数、合并新贡献，再判断是否入队。即使条目数相同，容器中的重复键、内层表、散列、扩容与额外索引也会带来不同的时间和空间成本。</p><h2 id="_2-按访问方式选择映射布局" tabindex="-1"><a class="header-anchor" href="#_2-按访问方式选择映射布局" aria-hidden="true">#</a> 2. 按访问方式选择映射布局</h2><p>论文第 4.1 节比较的候选布局包括（下标表示外层映射用的键：N 是节点，D 是源事实，E 是出口摘要 EndSummary）：</p><table><thead><tr><th style="text-align:left;">名称</th><th style="text-align:left;">结构</th><th style="text-align:left;">外层固定后还要查什么</th></tr></thead><tbody><tr><td style="text-align:left;">JF_old</td><td style="text-align:left;"><code>n → d₁ → d₂ → f</code></td><td style="text-align:left;">源事实、目标事实</td></tr><tr><td style="text-align:left;">JF_ND</td><td style="text-align:left;"><code>(n,d₁) → (d₂ → f)</code></td><td style="text-align:left;">目标事实</td></tr><tr><td style="text-align:left;">JF_N</td><td style="text-align:left;"><code>n → ((d₁,d₂) → f)</code></td><td style="text-align:left;">源目标事实对</td></tr><tr><td style="text-align:left;">JF_NE</td><td style="text-align:left;">JF_N 加独立的出口摘要表</td><td style="text-align:left;">同 JF_N；出口摘要另查独立表</td></tr></tbody></table>',7),y={href:"https://drops.dagstuhl.de/storage/00lipics/lipics-vol313-ecoop2024/LIPIcs.ECOOP.2024.36/LIPIcs.ECOOP.2024.36.pdf",target:"_blank",rel:"noopener noreferrer"},b=s(`<p>在我们的三条记录中：</p><ul><li>JF_ND 为 <code>(n,p)</code> 和 <code>(n,q)</code> 各建立一个内层表。</li><li>JF_N 只为 n 建立一个内层表，里面有 <code>(p,a)</code>、<code>(p,b)</code>、<code>(q,b)</code> 三个键。</li></ul><p>若经常一次处理固定 n 下的很多事实，JF_N 能共用一次外层查找；若经常固定 n、p 查询，JF_ND 的内层表更直接，但可能需要更多小表。</p><h2 id="_3-批处理-复用外层查找" tabindex="-1"><a class="header-anchor" href="#_3-批处理-复用外层查找" aria-hidden="true">#</a> 3. 批处理：复用外层查找</h2><p>原本每次更新都从总表查起（下面以 JF_N 的形状为例）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>for 每个目标事实 d2:
    old = table[n][d1,d2]
    new = old ⊔ candidate
    有变化则保存并调度
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>若这一批的 n 固定，可把查找移到循环外：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>row = table[n]
for 每个目标事实 d2:
    old = row[d1,d2]
    new = old ⊔ candidate
    有变化则保存并调度
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>本例用 Join 表示函数合并，论文按自己的顺序写 Meet；存储优化不改变合并语义。一次批处理包含 k 次更新时，外层定位由 k 次降为一次，内层更新和变化检测仍然都要做。</p>`,9),m={href:"https://drops.dagstuhl.de/storage/00lipics/lipics-vol313-ecoop2024/LIPIcs.ECOOP.2024.36/LIPIcs.ECOOP.2024.36.pdf",target:"_blank",rel:"noopener noreferrer"},I=s('<h2 id="_4-有了摘要-能把方法内部条目全删掉吗" tabindex="-1"><a class="header-anchor" href="#_4-有了摘要-能把方法内部条目全删掉吗" aria-hidden="true">#</a> 4. 有了摘要，能把方法内部条目全删掉吗？</h2><p>条目**回收（garbage collection，GC）**释放后续不再需要的记录。判定条件来自 Arzt 的 IFDS 多线程 GC（ICSE 2021，<em>Sustainable Solving: Reducing the Memory Footprint of IFDS-Based Data Flow Analyses Using Intelligent Garbage Collection</em>）；本篇论文将它改为单线程定点调用，并扩展到 IDE。</p><p>calc 内部保存 <code>p→a</code>、<code>p→b</code>，出口保存 <code>p→ret</code>。部分内部条目可以回收，但摘要应用可能触发新传播，IDE 第二阶段也可能还要用它们求值，因此不能在摘要生成后立即全删。</p><p>论文第 4.2 节将生命周期与两类工作列表结合：</p><ul><li>PathWorkList：待处理的向前传播。</li><li>RetWorklist：待应用到调用者的摘要。</li></ul><p>回收某过程的中间条目，需要确认两个列表中都没有该过程或其传递被调用者的待办；还要保留后续需要的结果与值传播信息。论文第 4.2.2 节明确列出的保留项有两类：感兴趣节点（interesting nodes，客户端要查询值的位置，例如类型状态分析的状态转移语句、常量分析的分支条件）和所有调用点（阶段二算过程入口值要用）。出口摘要不可回收则是从 Arzt 的原设计和论文第 6.2 节对 JF_NE 的讨论推出的，论文正文没有单独列出。</p><p>假设 p 调用 q，此时：</p><ol><li>q 的摘要刚产生，仍在返回列表里等待应用给 p。</li><li>若此时只看到 PathWorkList 里没有 p 的条目就回收 p，后续摘要应用又会要求继续处理 p。</li><li>按回收条件，q 是 p 的被调者、q 又在 RetWorklist 里，所以 p 不满足条件；等 q 的摘要应用完并处理完由此产生的新任务，才能回收 p 的中间条目。</li></ol>',8),v={href:"https://drops.dagstuhl.de/storage/00lipics/lipics-vol313-ecoop2024/LIPIcs.ECOOP.2024.36/LIPIcs.ECOOP.2024.36.pdf",target:"_blank",rel:"noopener noreferrer"},C=s('<p>若业务必须查询所有节点的值，内部节点也都需要保留，回收空间就会缩小，甚至完全消失。</p><h2 id="_5-实验结果与比较基线" tabindex="-1"><a class="header-anchor" href="#_5-实验结果与比较基线" aria-hidden="true">#</a> 5. 实验结果与比较基线</h2><p>论文评估了 31 个 C/C++ 程序，使用类型状态分析（Typestate）、线性常量分析（LCA）和指令交互分析（IIA）；三者的事实域从稀疏到稠密依次增大，IIA 的事实数接近程序点数，是最重的负载。实验节点为 AMD EPYC 72F3，内存限制 250 GiB，超时限制四小时。下表来自表 3，列出平均比值及标准差；比值大于 1 表示改善，小于 1 表示该项变差：</p><table><thead><tr><th style="text-align:left;">分析</th><th style="text-align:left;">内存：旧/新</th><th style="text-align:left;">时间：旧/新</th></tr></thead><tbody><tr><td style="text-align:left;">IIA</td><td style="text-align:left;"><code>4.811 ± 1.192</code></td><td style="text-align:left;"><code>7.227 ± 2.042</code></td></tr><tr><td style="text-align:left;">LCA</td><td style="text-align:left;"><code>1.729 ± 0.365</code></td><td style="text-align:left;"><code>4.683 ± 2.150</code></td></tr><tr><td style="text-align:left;">Typestate</td><td style="text-align:left;"><code>0.968 ± 0.050</code></td><td style="text-align:left;"><code>1.162 ± 0.143</code></td></tr></tbody></table>',4),P=t("strong",null,"比较双方是原 IDESolver 与论文的新求解器 IDESolver++（使用 JF_old 布局）。",-1),E={href:"https://drops.dagstuhl.de/storage/00lipics/lipics-vol313-ecoop2024/LIPIcs.ECOOP.2024.36/LIPIcs.ECOOP.2024.36.pdf",target:"_blank",rel:"noopener noreferrer"},F=t("p",null,"换布局与开回收的增量收益由另外两组实验测量（论文第 6.2 节，表 4、图 6）。论文自己的结论是：没有对所有分析都最优的布局——JF_N、JF_NE 在 LCA 上内存最省，IIA 上反而是 JF_old 运行最快；单线程 GC 让 LCA 的内存平均降低约 12%（标准差约 10%），对 Typestate 几乎没有作用（不到 1%），并带来百分之几的运行时开销。把两项优化合起来（第 6.5 节），IIA 的内存与时间各改善约 6.9 倍，LCA 约 2.7 倍与 4.9 倍，Typestate 没有明显改善。不同分析的事实数量和稀疏程度不同，收益不能直接移植到 Java 污点分析。",-1),O=t("p",null,"还需将“完成的任务”“超时”“内存不足”一起看：从内存不足变为超时，不等于已经完成，也不必然意味着算法变慢。仅统计成功案例的平均耗时会遗漏这些差异。",-1),k=t("h2",{id:"_6-同一问题的其他路线",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#_6-同一问题的其他路线","aria-hidden":"true"},"#"),e(" 6. 同一问题的其他路线")],-1),S={href:"https://phasar.org/",target:"_blank",rel:"noopener noreferrer"},A=t("thead",null,[t("tr",null,[t("th",{style:{"text-align":"left"}},"路线"),t("th",{style:{"text-align":"left"}},"做法"),t("th",{style:{"text-align":"left"}},"减少的成本"),t("th",{style:{"text-align":"left"}},"代表")])],-1),L=t("td",{style:{"text-align":"left"}},"稀疏化",-1),J=t("td",{style:{"text-align":"left"}},"事实只在定义与使用它的语句之间传播，跳过与该事实无关的程序点",-1),N=t("td",{style:{"text-align":"left"}},"恒等边的传播次数与路径边数量",-1),D={style:{"text-align":"left"}},w=t("em",null,"Performance-Boosting Sparsification of the IFDS Algorithm",-1),B={href:"https://github.com/SVF-tools/SVF",target:"_blank",rel:"noopener noreferrer"},R=t("td",{style:{"text-align":"left"}},"按需求解",-1),q=t("td",{style:{"text-align":"left"}},"只从查询点出发，向前或向后探索到足以回答的范围",-1),V=t("td",{style:{"text-align":"left"}},"与查询无关的整程序传播",-1),G={style:{"text-align":"left"}},T={href:"https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ECOOP.2016.22",target:"_blank",rel:"noopener noreferrer"},W={href:"https://www.bodden.de/pubs/sab19context.pdf",target:"_blank",rel:"noopener noreferrer"},M=t("tr",null,[t("td",{style:{"text-align":"left"}},"摘要复用"),t("td",{style:{"text-align":"left"}},"跨方法复用摘要，库方法预先算好摘要"),t("td",{style:{"text-align":"left"}},"重复分析的工作量"),t("td",{style:{"text-align":"left"}},"FlowDroid 与 StubDroid 的方法摘要")],-1),z=t("td",{style:{"text-align":"left"}},"并行与增量",-1),U=t("td",{style:{"text-align":"left"}},"多线程或 GPU 并行求解；代码改动后只重算受影响部分",-1),H=t("td",{style:{"text-align":"left"}},"挂钟时间；增量还减少重算的工作量",-1),Y={style:{"text-align":"left"}},j={href:"https://www.bodden.de/pubs/ab14reviser.pdf",target:"_blank",rel:"noopener noreferrer"},K=s('<p>稀疏化需要定义使用关系，按需求解需要具体查询，回收依赖调度不变式。摘要复用减少重复工作，回收减少保留的条目，并行主要缩短挂钟时间；应按实际瓶颈选择或组合。</p><h2 id="_7-怎样迁移到自己的求解器" tabindex="-1"><a class="header-anchor" href="#_7-怎样迁移到自己的求解器" aria-hidden="true">#</a> 7. 怎样迁移到自己的求解器？</h2><ol><li>记录跳转函数条目数、各索引规模、容器分配，以及最频繁的查询键组合。</li><li>对固定节点的一批更新，测试复用内层表能节省多少查找，同时测量小表增多的代价。</li><li>固定输入、模型、种子与预算，分别测量布局、批处理和回收的收益。</li><li>比较优化前后各查询点的值与报告，确认结果一致。</li><li>同时记录内存峰值、耗时、超时与 OOM，让未完成的任务也进入对照。</li></ol><h2 id="本篇要点" tabindex="-1"><a class="header-anchor" href="#本篇要点" aria-hidden="true">#</a> 本篇要点</h2><ul><li><strong>布局与批处理</strong>应贴合查询方式，减少容器和重复查找的成本。</li><li><strong>回收</strong>须检查两个工作列表中的本过程及传递被调者，并保留查询点、所需调用点与出口摘要。</li><li>性能倍数依赖比较基线与分析负载，不能直接移植到 Java 污点分析。</li><li>优化前先测瓶颈，优化后核对结果，并将超时与 OOM 纳入评估。</li></ul><p>对象别名在下一篇展开；库建模与反射等后续专题见系列总览。</p>',6);function Q(X,Z){const n=i("RouterLink"),d=i("ExternalLinkIcon");return r(),c("div",null,[_,h(" more "),t("p",null,[l(n,{to:"/static-analysis/08-ide.html"},{default:a(()=>[e("第 08 篇")]),_:1}),e("的跳转函数 "),f,e(" 在大程序中数量庞大，存储与访问成本可能成为瓶颈。")]),t("p",null,[e("ECOOP 2024 论文 "),g,e("（Schiebel、Sattler、Schubert、Apel、Bodden）优化了跳转函数表的布局与条目回收。以下用自建条目说明布局、批处理和回收，性能数据引用论文实验。"),t("a",u,[e("论文与出版信息"),l(d)])]),x,t("p",null,[e("JF_old 在新求解器中保留了原来的嵌套形状，但移除了旧实现维护的多索引，比较实验时需要计入这项差异。"),t("a",y,[e("论文第 4.1 节"),l(d)])]),b,t("p",null,[e("论文算法 1 将这样的局部视图传给 Propagate（论文中“把一条跳转函数合并进表并按需入队”的过程），在保留全部更新的同时复用查找结果。"),t("a",m,[e("论文算法 1 与表 2"),l(d)])]),I,t("p",null,[e("论文先处理完 PathWorkList，再处理完 RetWorklist，随后调用回收（算法 3 第 9 行）。此时返回应用可能已向 PathWorkList 加入新任务，回收仍须检查两个列表；外层循环继续，直到二者都为空。"),t("a",v,[e("论文算法 2、3 与第 4.2.2 节"),l(d)])]),C,t("p",null,[P,e(" 7.227 倍反映了索引、批处理等实现的整体变化。Typestate 的内存比小于 1，论文给出的原因是新求解器预分配了较大的缓冲区，而 Typestate 事实太稀疏、填不满。"),t("a",E,[e("论文第 6 节，尤其表 3"),l(d)])]),F,O,k,t("p",null,[e("论文基于 "),t("a",S,[e("PhASAR"),l(d)]),e(" 优化存储与访问。还可以减少传播工作量，或改变工作的执行方式：")]),t("table",null,[A,t("tbody",null,[t("tr",null,[L,J,N,t("td",D,[e("He 等，"),w,e("（ASE 2020）；"),t("a",B,[e("SVF"),l(d)]),e(" 是另一类基于稀疏值流图的框架")])]),t("tr",null,[R,q,V,t("td",G,[t("a",T,[e("Boomerang"),l(d)]),e(" 的按需别名查询；"),t("a",W,[e("同步下推系统"),l(d)]),e("同时处理调用与字段两种括号（"),l(n,{to:"/static-analysis/07-ifds.html"},{default:a(()=>[e("第 07 篇")]),_:1}),e("第 6.3 节）")])]),M,t("tr",null,[z,U,H,t("td",Y,[e("Reviser（"),t("a",j,[e("Arzt 与 Bodden，ICSE 2014"),l(d)]),e("）的增量 IFDS/IDE；Arzt 2021、He 等 2023 的多线程求解与回收；Yu 等 2020 的 GPU 并行")])])])]),K,t("p",null,[l(n,{to:"/static-analysis/09-symbolic-execution-clang.html"},{default:a(()=>[e("上一篇：09 符号执行与 Clang")]),_:1}),e(" · "),l(n,{to:"/static-analysis/11-pointer-analysis.html"},{default:a(()=>[e("下一篇：11 对象、别名与指针分析")]),_:1}),e(" · "),l(n,{to:"/static-analysis/"},{default:a(()=>[e("返回系列总览")]),_:1})])])}const et=o(p,[["render",Q],["__file","10-ide-solver-engineering.html.vue"]]);export{et as default};
